email, maple_monk_id FROM INT WHERE COALESCE(cast(contact_num as string), cast(email as string)) IS NOT NULL; CREATE OR REPLACE TABLE `project-dea872a4-8550-4cff-a8c`.maplemonk.miniklub_marketplace_sales_consolidated AS SELECT mm.final_marketplace, COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, sum(ifnull(quantity, 0)) over(partition by reference_code order by 1) Order_Quantity, case WHEN upper(m.final_shipping_status) LIKE \'%RTO%\' OR upper(m.final_shipping_status) LIKE \'%FAILURE%\' OR upper(m.order_status) LIKE \'%UNFULFILLABLE%\' OR upper(m.order_status) LIKE \'%RETURNED TO SELLER%\' OR upper(m.order_status) LIKE \'%RETURNING TO SELLER%\' OR upper(m.order_status) LIKE \'%UNDELIVERED%\' OR (upper(m.order_status) LIKE \'%CANCEL%\' AND upper(m.final_shipping_status) = \'IN TRANSIT\') THEN 1 ELSE 0 end as RTO_flag, case when (upper(m.final_shipping_status) like \'%RETURN%\' or upper(m.order_status) = \'RETURNED\') then 1 else 0 end as DTO_flag, case when upper(m.final_shipping_status) like \'%RTO%\' or upper(m.final_shipping_status) like \'%FAILURE%\' or upper(m.order_status) like \'%UNFULFILLABLE%\' or upper(m.order_status) like \'%RETURNED TO SELLER%\' or upper(m.order_status) like \'%RETURNING TO SELLER%\' or upper(m.order_status) like \'%UNDELIVERED%\' or (upper(m.order_status) like \'%CANCEL%\' and upper(m.final_shipping_status) = \'IN TRANSIT\') then m.selling_price ELSE 0 end as RTO_value, case when (upper(m.final_shipping_status) like \'%RETURN%\' or upper(m.order_status) = \'RETURNED\') then m.selling_price else 0 end as DTO_value, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM `project-dea872a4-8550-4cff-a8c`.maplemonk.miniklub_market